SELECT contour.register_causal_profile('f0000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000501',decode('b0bcc91455463d2dd48c438292abe1063ed7d3430459ead5ec48423c9ba1b510','hex'));
DO $$ BEGIN
